metadata.code:
def _undirected_unique_edges(edges: list[dict], id_to_idx: dict[str, int]) -> np.ndarray:
    pairs: set[tuple[int, int]] = set()
    for edge in edges:
        if edge.get("type") != "CALLS":
            continue
        src = id_to_idx.get(edge.get("source"))
        dst = id_to_idx.get(edge.get("target"))
        if src is None or dst is None or src == dst:
            continue
        a, b = (src, dst) if src < dst else (dst, src)
        pairs.add((a, b))
    if not pairs:
        return np.zeros((2, 0), dtype=np.int64)
    ordered = np.array(sorted(pairs), dtype=np.int64)
    return ordered.T

def _split_edges(edge_index: np.ndarray) -> dict[str, np.ndarray]:
    rng = random.Random(RNG_SEED)
    pairs = list(zip(edge_index[0].tolist(), edge_index[1].tolist()))
    rng.shuffle(pairs)

    n = len(pairs)
    n_train = int(n * 0.8)
    n_val = int(n * 0.1)
    chunks = {
        "train": pairs[:n_train],
        "val": pairs[n_train:n_train + n_val],
        "test": pairs[n_train + n_val:],
    }
    result = {}
    for name, chunk in chunks.items():
        result[name] = np.array(chunk, dtype=np.int64).T if chunk else np.zeros((2, 0), dtype=np.int64)
    return result

def sample_negative_edges(num_nodes: int, positives: torch.Tensor, count: int, device: torch.device) -> torch.Tensor:
    existing = set()
    pos_cpu = positives.detach().cpu().numpy()
    for a, b in pos_cpu.T:
        if a == b:
            continue
        x, y = (int(a), int(b)) if a < b else (int(b), int(a))
        existing.add((x, y))

    negatives: set[tuple[int, int]] = set()
    while len(negatives) < count:
        a = random.randrange(num_nodes)
        b = random.randrange(num_nodes)
        if a == b:
            continue
        x, y = (a, b) if a < b else (b, a)
        if (x, y) in existing or (x, y) in negatives:
            continue
        negatives.add((x, y))
    return torch.tensor(sorted(negatives), dtype=torch.long, device=device).T

def forward(self, x: torch.Tensor, edge_index: torch.Tensor) -> torch.Tensor:
        h = self.layer1(x, edge_index)
        h = F.relu(h)
        h = F.dropout(h, p=self.dropout, training=self.training)
        h = self.layer2(h, edge_index)
        return F.normalize(h, p=2, dim=1)

